@st.cache_data(ttl=300, show_spinner=False)
def fetch_meta_aggregate_insights(
    client_id,
    account_id,
    start_date,
    end_date,
    level,
    api_filters,
    api_key,
):
    account_edge = account_id if str(account_id).startswith("act_") else f"act_{account_id}"
    fields = ["impressions", "reach", "results", "cost_per_result"]
    if level in ("campaign", "adset", "ad"):
        fields += ["campaign_id", "campaign_name"]
    if level in ("adset", "ad"):
        fields += ["adset_id", "adset_name"]
    if level == "ad":
        fields += ["ad_id", "ad_name", "actions", "clicks", "spend"]

    s_iso = start_date.isoformat() if hasattr(start_date, "isoformat") else str(start_date)
    e_iso = end_date.isoformat() if hasattr(end_date, "isoformat") else str(end_date)
    params = {
        "fields": ",".join(fields),
        "level": level,
        "time_range": json.dumps({
            "since": s_iso[:10] if len(s_iso) >= 10 else s_iso,
            "until": e_iso[:10] if len(e_iso) >= 10 else e_iso,
        }),
        "limit": 500,
    }
    if api_filters:
        params["filtering"] = json.dumps([
            {
                "field": field,
                "operator": "IN" if isinstance(value, list) else "EQUAL",
                "value": value if isinstance(value, list) else [value],
            }
            for field, value in api_filters.items()
        ])

    rows = []
    seen_cursors = set()
    try:
        while True:
            response = _meta_proxy_get(
                client_id,
                account_id,
                api_key,
                f"{account_edge}/insights",
                params,
            )
            if response.status_code != 200:
                return [], f"No se pudieron cargar insights Meta ({response.status_code})."

            payload = response.json()
            for insight in payload.get("data", []):
                actions = insight.get("actions") or []
                result_entries = insight.get("results") or []
                result_indicator = (
                    str(result_entries[0].get("indicator") or "")
                    if result_entries else ""
                )
                result_value = _meta_indicator_value(result_entries, result_indicator)
                result_cost = _meta_indicator_value(
                    insight.get("cost_per_result"), result_indicator
                )
                rows.append({
                    "campaign_id": insight.get("campaign_id") or "",
                    "campaign_name": insight.get("campaign_name") or "",
                    "adset_id": insight.get("adset_id") or "",
                    "adset_name": insight.get("adset_name") or "",
                    "ad_id": insight.get("ad_id") or "",
                    "ad_name": insight.get("ad_name") or "",
                    "impressions": extract_metric(insight, ["impressions"]),
                    "reach": extract_metric(insight, ["reach"]),
                    "spend": extract_metric(insight, ["spend"]),
                    "clicks": extract_metric(insight, ["clicks"]),
                    "result_indicator": result_indicator,
                    "results": result_value,
                    "cost_per_result": result_cost,
                    "lead": sum(
                        extract_metric(action, ["value"])
                        for action in actions
                        if action.get("action_type") in {
                            "lead",
                            "onsite_conversion.lead_grouped",
                            "offsite_conversion.fb_pixel_lead",
                        }
                    ),
                    "post_engagement": sum(
                        extract_metric(action, ["value"])
                        for action in actions
                        if action.get("action_type") in {
                            "post_engagement",
                            "like",
                            "comment",
                            "post_reaction",
                        }
                    ),
                })

            after = (payload.get("paging") or {}).get("cursors", {}).get("after")
            if not after or after in seen_cursors:
                break
            seen_cursors.add(after)
            params["after"] = after
        return rows, None
    except Exception as e:
        return [], f"Error cargando insights Meta: {e}"


@st.cache_data(ttl=300, show_spinner=False)
def fetch_meta_ad_previews(client_id, account_id, preview_targets, api_key):
def meta_base_campaign_name(value):
    return re.sub(r"_(facebook|instagram|audience_network|messenger|whatsapp|unknown|threads)$", "", str(value), flags=re.I)


def meta_campaigns_with_impressions(frame):
    if frame.empty or not {"campaign_name", "impressions"}.issubset(frame.columns):
        return set()

    totals = pd.to_numeric(frame["impressions"], errors="coerce").fillna(0).groupby(
        frame["campaign_name"].map(meta_base_campaign_name)
    ).sum()
    return set(totals[totals > 0].index)


def select_meta_ad_winners(ad_rows, ranked_campaigns_by_metric):
    winners = {}
    for metric, campaign_names in ranked_campaigns_by_metric.items():
        for campaign_name in campaign_names:
            candidates = [
                row
                for row in ad_rows
                if meta_base_campaign_name(row.get("campaign_name", "")) == campaign_name
            ]
            if candidates:
                winners[(metric, campaign_name)] = min(
                    candidates,
                    key=lambda row: (
                        -extract_metric(row, [metric]),
                        -extract_metric(row, ["impressions"]),
                        str(row.get("ad_id") or ""),
                    ),
                )
    return winners


def select_meta_top_ads(ad_rows, metrics, limit=3):
    return {
        metric: sorted(
            (row for row in ad_rows if row.get("ad_id")),
            key=lambda row: (
                -extract_metric(row, [metric]),
                -extract_metric(row, ["impressions"]),
                str(row.get("ad_id")),
            ),
        )[:limit]
        for metric in metrics
    }


